import json

# Count endpoints (cells with only 1 neighbor)
def count_endpoints(cells):
    if not cells:
        return 0
    grid = set(cells)
    endpoints = 0
    for r, c in cells:
        neighbors = [(r-1, c), (r+1, c), (r, c-1), (r, c+1)]
        n_count = sum(1 for n in neighbors if n in grid)
        if n_count == 1:
            endpoints += 1
    return endpoints

